package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import de.eldoria.graph.std.runtime.Timer;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.entity.Zombie;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.inventory.EntityEquipment;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemType;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class InvisibleZombieBehaviour implements CompiledBehaviour {
    private static final PotionEffectType INVISIBILITY = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:invisibility");

    private static final EquipmentSlot HAND = EquipmentSlot.HAND;

    private static final ItemType AIR = Registries.entry(RegistryKey.ITEM, "minecraft:air");

    private static final EquipmentSlot HEAD = EquipmentSlot.HEAD;

    private static final EquipmentSlot CHEST = EquipmentSlot.CHEST;

    private static final EquipmentSlot LEGS = EquipmentSlot.LEGS;

    private static final EquipmentSlot FEET = EquipmentSlot.FEET;

    private static final TimeUnit SECONDS = TimeUnit.SECONDS;

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private final MobContext context;

    private Timer damagedTimer;

    private Cooldown cooldown;

    public InvisibleZombieBehaviour(MobContext context) {
        this.context = context;
        // node #1 timer.reset
        this.damagedTimer = new Timer();
        // node #44 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onDamageByEntity(EntityDamageByEntityEvent event) {
        // node #6 event.damage_by_entity
        // node #7 timer.reset
        this.damagedTimer.reset();
        // node #8 living_entity.remove_potion_effect
        ((Zombie) this.context.entity()).removePotionEffect(INVISIBILITY);
        // node #9
    }

    @Override
    public void onDamageByPlayer(EntityDamageByEntityEvent event) {
        // node #15 event.damage_by_player
        // node #16 timer.reset
        this.damagedTimer.reset();
        // node #17 living_entity.remove_potion_effect
        ((Zombie) this.context.entity()).removePotionEffect(INVISIBILITY);
        // node #18
    }

    @Override
    public void onSpawn() {
        // node #33 mob.spawn
        // node #35 equipment.equip
        // node #34 mob.read
        final EntityEquipment equipment = ((Zombie) this.context.entity()).getEquipment();
        equipment.setItem(HAND, AIR.createItemStack());
        // node #36 equipment.equip
        equipment.setItem(HEAD, AIR.createItemStack());
        // node #37 equipment.equip
        equipment.setItem(CHEST, AIR.createItemStack());
        // node #38 equipment.equip
        equipment.setItem(LEGS, AIR.createItemStack());
        // node #39 equipment.equip
        equipment.setItem(FEET, AIR.createItemStack());
        // node #40
    }

    @Override
    public void onTick() {
        // node #51 mob.tick
        // node #56 flow.branch
        // node #52 timer.elapsed
        final double elapsed = this.damagedTimer.elapsed(SECONDS);
        if (!(elapsed >= 10.0d)) return;
        // node #55 flow.branch
        // node #53 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(1000.0d));
        if (!cooldown) return;
        // node #54 living_entity.apply_effect
        ((Zombie) this.context.entity()).addPotionEffect(new PotionEffect(INVISIBILITY, (int) (2.0d * 20), 0, true, true));
        // node #57
    }
}
